impl<T: gx::Real> Vector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = t0 + t1;
        let t4 = t2 + t3;
        t4
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (16 mul, 7 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Vector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = t0 * t0;
        let t4 = t0 * t1;
        let t5 = t0 * t2;
        let t6 = t1 * t1;
        let t7 = t1 * t2;
        let t8 = t2 * t2;
        let t9 = t3 + t6;
        let t10 = t8 + t9;
        let t11 = t4 + t5;
        let t12 = t7 + t11;
        let t13 = t12 * T::from_i64(2);
        let t14 = t10 + t13;
        let t15 = t14.recip();
        let t16 = t0 * t15;
        let t17 = t1 * t15;
        let t18 = t2 * t15;
        let t19 = t16 + t17;
        let t20 = t18 + t19;
        let t21 = x[0] * t20;
        let t22 = x[1] * t20;
        let t23 = x[2] * t20;
        Vector::from_coeffs([t21, t22, t23])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p1 = x[1] * x[1];
        let p2 = x[2] * x[2];
        let p3 = p0 + p1;
        let p4 = p2 + p3;
        let s0 = (p4).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        gx::Unit::new_unchecked(Vector::from_coeffs([t0, t1, t2]))
    }

}

#[doc = "A bivector: an oriented plane, or the generator of a rotation."]
///
/// Blades, in coefficient order: `[e23, e31, e12]`.
///
/// `S` lists the open slots: `Bivector` (that is, `Bivector<()>`) is a value, `Bivector<(A,)>` a
/// linear map from `A`, `Bivector<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Bivector<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 3],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Bivector<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Bivector<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Bivector<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Bivector<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Bivector");
        for (b, c) in <Bivector as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Bivector {
    const N: usize = 3;
    const NAME: &'static str = "Bivector";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e23", "e31", "e12"];
    type Arr<X: gx::Elem> = [X; 3];
    type Mv<S: gx::Slots, T: gx::Coef> = Bivector<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(f: impl FnMut(usize) -> X) -> [X; 3] {
        core::array::from_fn(f)
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 3], f: impl FnMut(&X) -> Y) -> [Y; 3] {
        a.each_ref().map(f)
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 3],
        b: &[Y; 3],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 3] {
        core::array::from_fn(|i| f(&a[i], &b[i]))
    }
}

