impl<T: gx::Real> Bivector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = t0 + t1;
        let t4 = t2 + t3;
        t4
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (16 mul, 7 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Bivector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = t0 * t0;
        let t4 = t0 * t1;
        let t5 = t0 * t2;
        let t6 = t1 * t1;
        let t7 = t1 * t2;
        let t8 = t2 * t2;
        let t9 = t3 + t6;
        let t10 = t8 + t9;
        let t11 = t4 + t5;
        let t12 = t7 + t11;
        let t13 = t12 * T::from_i64(2);
        let t14 = t10 + t13;
        let t15 = t14.recip();
        let t16 = t0 * t15;
        let t17 = t1 * t15;
        let t18 = t2 * t15;
        let t19 = t16 + t17;
        let t20 = t18 + t19;
        let t21 = x[0] * t20;
        let t22 = x[1] * t20;
        let t23 = x[2] * t20;
        let t24 = -t21;
        let t25 = -t22;
        let t26 = -t23;
        Bivector::from_coeffs([t24, t25, t26])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p1 = x[1] * x[1];
        let p2 = x[2] * x[2];
        let p3 = p0 + p1;
        let p4 = p2 + p3;
        let s0 = (p4).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        gx::Unit::new_unchecked(Bivector::from_coeffs([t0, t1, t2]))
    }

    /// The exponential, a unit versor: `exp(B) = C(BÂ²) + S(BÂ²) B` with `BÂ²` a Study number.
    #[inline]
    #[allow(unused_variables)]
    pub fn exp(self) -> gx::Unit<Rotor<(), T>> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p1 = x[1] * x[1];
        let p2 = x[2] * x[2];
        let p3 = p0 + p1;
        let p4 = p2 + p3;
        let p5 = -p4;
        let [c0, c1, s0, s1] = gx::study::exp_coeffs_rotation(p5, T::from_i64(0));
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        gx::Unit::new_unchecked(Rotor::from_coeffs([c0, t0, t1, t2]))
    }

}

#[doc = "The unit volume element `e123`."]
///
/// Blades, in coefficient order: `[e123]`.
///
/// `S` lists the open slots: `Pseudoscalar` (that is, `Pseudoscalar<()>`) is a value, `Pseudoscalar<(A,)>` a
/// linear map from `A`, `Pseudoscalar<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Pseudoscalar<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 1],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Pseudoscalar<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

