impl<T: gx::Real> Rotor<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t4 = t0 + t1;
        let t5 = t2 + t3;
        let t6 = t4 + t5;
        t6
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (23 mul, 12 add, 1 div).
    #[inline]
    pub fn inverse(self) -> Rotor<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t4 = t0 * t0;
        let t5 = t0 * t1;
        let t6 = t0 * t2;
        let t7 = t0 * t3;
        let t8 = t1 * t1;
        let t9 = t1 * t2;
        let t10 = t1 * t3;
        let t11 = t2 * t2;
        let t12 = t2 * t3;
        let t13 = t3 * t3;
        let t14 = t4 + t8;
        let t15 = t11 + t13;
        let t16 = t14 + t15;
        let t17 = t5 + t6;
        let t18 = t7 + t17;
        let t19 = t9 + t10;
        let t20 = t12 + t19;
        let t21 = t18 + t20;
        let t22 = t21 * T::from_i64(2);
        let t23 = t16 + t22;
        let t24 = t23.recip();
        let t25 = t0 * t24;
        let t26 = t1 * t24;
        let t27 = t2 * t24;
        let t28 = t3 * t24;
        let t29 = t25 + t26;
        let t30 = t27 + t28;
        let t31 = t29 + t30;
        let t32 = x[0] * t31;
        let t33 = x[1] * t31;
        let t34 = x[2] * t31;
        let t35 = x[3] * t31;
        let t36 = -t33;
        let t37 = -t34;
        let t38 = -t35;
        Rotor::from_coeffs([t32, t36, t37, t38])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p1 = x[1] * x[1];
        let p2 = x[2] * x[2];
        let p3 = x[3] * x[3];
        let p4 = p0 + p1;
        let p5 = p2 + p3;
        let p6 = p4 + p5;
        let s0 = (p6).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Rotor::from_coeffs([t0, t1, t2, t3]))
    }

    /// The principal square root of a unit versor, `normalize(1 + R)` (not defined for `R = -1`).
    #[inline]
    pub fn sqrt(self) -> gx::Unit<Self> {
        let mut c = self.c;
        c[0] = c[0] + T::one();
        Rotor::from_coeffs(c).normalized()
    }

}

impl<T: gx::Real> gx::Log<Bivector<(), T>> for gx::Unit<Rotor<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Bivector<(), T> {
        let x = self.into_inner().c;
        let p0 = x[1] * x[1];
        let p1 = x[2] * x[2];
        let p2 = x[3] * x[3];
        let p3 = p0 + p1;
        let p4 = p2 + p3;
        let p5 = -p4;
        let [h0, h1] = gx::study::log_coeffs_rotation((x[0], T::from_i64(0)), (p5, T::from_i64(0)));
        let t0 = x[1] * h0;
        let t1 = x[2] * h0;
        let t2 = x[3] * h0;
        Bivector::from_coeffs([t0, t1, t2])
    }
}

#[doc = "The odd subalgebra: rotoreflections."]
///
/// Blades, in coefficient order: `[e1, e2, e3, e123]`.
///
/// `S` lists the open slots: `Odd` (that is, `Odd<()>`) is a value, `Odd<(A,)>` a
/// linear map from `A`, `Odd<(A, B)>` a bilinear map. `T` is the coefficient type.
#[repr(C)]
pub struct Odd<S: gx::Slots = (), T: gx::Coef = f32> {
    /// Coefficients, output first: `c[i]` is the slot array of blade `i`.
    pub c: [S::Arr<T>; 4],
}

impl<S: gx::Slots, T: gx::Coef> Clone for Odd<S, T> {
    #[inline(always)]
    fn clone(&self) -> Self {
        *self
    }
}

impl<S: gx::Slots, T: gx::Coef> Copy for Odd<S, T> {}

impl<S: gx::Slots, T: gx::Coef> PartialEq for Odd<S, T> {
    fn eq(&self, other: &Self) -> bool {
        self.c == other.c
    }
}

impl<S: gx::Slots, T: gx::Coef> core::fmt::Debug for Odd<S, T> {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut d = f.debug_struct("Odd");
        for (b, c) in <Odd as gx::Kind>::BLADES.iter().zip(self.c.iter()) {
            d.field(b, c);
        }
        d.finish()
    }
}

impl gx::Kind for Odd {
    const N: usize = 4;
    const NAME: &'static str = "Odd";
    const MODULE: &'static str = module_path!();
    const BLADES: &'static [&'static str] = &["e1", "e2", "e3", "e123"];
    type Arr<X: gx::Elem> = [X; 4];
    type Mv<S: gx::Slots, T: gx::Coef> = Odd<S, T>;
    type Scalar = Scalar;
    #[inline(always)]
    fn arr_from_fn<X: gx::Elem>(f: impl FnMut(usize) -> X) -> [X; 4] {
        core::array::from_fn(f)
    }
    #[inline(always)]
    fn arr_map<X: gx::Elem, Y: gx::Elem>(a: &[X; 4], f: impl FnMut(&X) -> Y) -> [Y; 4] {
        a.each_ref().map(f)
    }
    #[inline(always)]
    fn arr_zip<X: gx::Elem, Y: gx::Elem, Z: gx::Elem>(
        a: &[X; 4],
        b: &[Y; 4],
        mut f: impl FnMut(&X, &Y) -> Z,
    ) -> [Z; 4] {
        core::array::from_fn(|i| f(&a[i], &b[i]))
    }
}

