    /// Construct from output-first coefficients.
    #[inline(always)]
    pub const fn from_coeffs(c: [S::Arr<T>; 4]) -> Self {
        Odd { c }
    }

    /// All coefficients zero.
    #[inline(always)]
    pub fn zero() -> Self {
        Odd { c: [S::from_flat(&mut |_| T::zero(), 0); 4] }
    }

    /// Fill the first open slot with a value, or compose a map into it.
