impl<T: gx::Real> Multivector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t4 = x[4] * x[4];
        let t5 = x[5] * x[5];
        let t6 = x[6] * x[6];
        let t7 = x[7] * x[7];
        let t8 = t0 + t1;
        let t9 = t2 + t3;
        let t10 = t8 + t9;
        let t11 = t4 + t5;
        let t12 = t6 + t7;
        let t13 = t11 + t12;
        let t14 = t10 + t13;
        t14
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

}

