impl<S: gx::Slots, T: gx::Coef> gx::Transform<Scalar<S, T>> for Vector<(), T> {
    type Output = Scalar<S, T>;
    #[inline(always)]
    fn transform(self, x: Scalar<S, T>) -> Scalar<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 1>(&x.c) {
        let t0 = v[0] * v[0];
        let t1 = v[1] * v[1];
        let t2 = v[2] * v[2];
        let t3 = t0 + t1;
        let t4 = t2 + t3;
        let t5 = xv[0] * t4;
            return Scalar { c: gx::slots::from_values::<S, T, 1>([t5]) };
        }
        let m0 = v[0] * v[0];
        let m1 = v[1] * v[1];
        let m2 = v[2] * v[2];
        let m3 = m0 + m1;
        let m4 = m2 + m3;
        let x = x.c.map(gx::SlotArr::<S, T>);
        Scalar { c: [(x[0].scale(m4)).0] }
    }
}

